go_ethereum_CalcRequestsHash.code:
h1, h2 := sha256.New(), sha256.New()
var buf common.Hash
for _, item := range requests {
    if len(item) > 1 {
        h1.Reset()
        h1.Write(item)
        h2.Write(h1.Sum(buf[:0]))
    }
}
h2.Sum(buf[:0])
return buf

